import { test, expect } from '@playwright/test';

test.describe('Task Creation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks/new');
  });

  test('should display the task creation form', async ({ page }) => {
    const formTitle = await page.getByRole('heading', { name: /create new task/i });
    await expect(formTitle).toBeVisible();

    const taskNameInput = await page.getByLabel('Task Name');
    await expect(taskNameInput).toBeVisible();

    const taskDescriptionInput = await page.getByLabel('Description');
    await expect(taskDescriptionInput).toBeVisible();

    const saveButton = await page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();
  });

  test('should create a new task successfully', async ({ page }) => {
    await page.getByLabel('Task Name').fill('New Task');
    await page.getByLabel('Description').fill('This is a new task description.');
    await page.getByRole('button', { name: /save/i }).click();

    const successMessage = await page.getByText(/task created successfully/i);
    await expect(successMessage).toBeVisible();
  });
});
